public int[] jimOrdersBrute(int[][] orders) {
    int n = orders.length;
    boolean[] served = new boolean[n];
    int[] result = new int[n];
    for (int r = 0; r < n; r++) {
        int best = -1;
        for (int i = 0; i < n; i++) {
            if (served[i]) continue;
            if (best == -1) { best = i; continue; }
            long si = orders[i][0] + (long) orders[i][1];
            long sb = orders[best][0] + (long) orders[best][1];
            if (si < sb || (si == sb && i < best)) best = i;
        }
        served[best] = true;
        result[r] = best + 1;
    }
    return result;
}

