def jim_orders_brute(orders: list[list[int]]) -> list[int]:
    n = len(orders)
    served = [False] * n
    result = []
    for _ in range(n):
        best = -1
        for i in range(n):
            if served[i]:
                continue
            if best == -1:
                best = i
                continue
            si = orders[i][0] + orders[i][1]
            sb = orders[best][0] + orders[best][1]
            if si < sb or (si == sb and i < best):
                best = i
        served[best] = True
        result.append(best + 1)
