public int[] jimOrders(int[][] orders) {
    int n = orders.length;
    Integer[] ids = new Integer[n];
    for (int i = 0; i < n; i++) ids[i] = i;
    Arrays.sort(ids, (a, b) -> {
        long sa = orders[a][0] + (long) orders[a][1];
        long sb = orders[b][0] + (long) orders[b][1];
        if (sa != sb) return Long.compare(sa, sb);
        return Integer.compare(a, b);
    });
    int[] result = new int[n];
    for (int i = 0; i < n; i++) result[i] = ids[i] + 1;
    return result;
}

